-- =============================================================================
-- Decisions — single source of truth for OA decisions, replacing the hardcoded
-- src/data/decisions.ts array. The decisions page reads from this table; admins
-- can edit status / final_answer in the UI without a deploy.
--
-- monetary_kind + monetary_value link a confirmed decision to tracker_settings:
-- when a decision sets a dollar amount (e.g., monthly dues), the tracker page
-- consumes that value as authoritative.
--
-- Idempotent: safe to re-run.
-- =============================================================================

create table if not exists decisions (
  id              text primary key,
  question_id     text,
  category        text not null,
  topic           text not null,
  status          text not null check (status in ('confirmed','tabled','remaining')),
  final_answer    text,
  meeting_date    date,
  notes           text,

  -- Tracker integration: when a confirmed decision encodes a dollar amount,
  -- these surface it. Null on decisions without monetary content.
  monetary_kind   text check (monetary_kind in (
                    'initial_contribution',
                    'monthly_dues',
                    'capital_call_threshold',
                    'spending_authority_threshold',
                    'max_personal_risk_year_one'
                  )),
  monetary_value  numeric(12,2),

  created_at      timestamptz not null default now(),
  created_by      text,
  updated_at      timestamptz not null default now(),
  updated_by      text,
  deleted_at      timestamptz
);

create index if not exists decisions_status_idx       on decisions(status) where deleted_at is null;
create index if not exists decisions_question_id_idx  on decisions(question_id) where deleted_at is null;
create index if not exists decisions_monetary_kind_idx on decisions(monetary_kind) where deleted_at is null and status = 'confirmed';

-- View: confirmed monetary values, one row per kind. tracker_settings reads
-- these as authoritative when present.
create or replace view decisions_monetary_values as
  select monetary_kind, monetary_value, id as decision_id, final_answer, meeting_date
    from decisions
   where deleted_at is null
     and status = 'confirmed'
     and monetary_kind is not null
     and monetary_value is not null;

-- Seed from the existing src/data/decisions.ts array. on conflict do nothing
-- so re-runs after manual edits don't clobber.
insert into decisions (id, question_id, category, topic, status, final_answer, meeting_date, notes, created_by)
select t.id, t.question_id, t.category, t.topic, t.status, t.final_answer,
       case when t.meeting_date is not null and t.meeting_date <> '' then t.meeting_date::date else null end,
       t.notes, 'system'
